   158	    const handleStateChange = (state: NavigationState | undefined) => {
   159	        if (!state) {
   160	            return;
   161	        }
   162	        const currentRoute = navigationRef.getCurrentRoute();
   163	        Firebase.log(`[NAVIGATION] screen: ${currentRoute?.name}, params: ${JSON.stringify(currentRoute?.params ?? {})}`);
   164	
   165	        const activeWorkspaceID = getPolicyIDFromState(state as NavigationState<RootStackParamList>);
   166	        // Performance optimization to avoid context consumers to delay first render
   167	        setTimeout(() => {
   168	            currentReportIDValue?.updateCurrentReportID(state);
   169	            setActiveWorkspaceID(activeWorkspaceID);
   170	        }, 0);
   171	        parseAndLogRoute(state);
   172	
   173	        // We want to clean saved scroll offsets for screens that aren't anymore in the state.
   174	        cleanStaleScrollOffsets(state);
   175	    };
   176	
   177	    return (
   178	        <NavigationContainer
   179	            initialState={initialState}
   180	            onStateChange={handleStateChange}
   181	            onReady={onReady}
   182	            theme={navigationTheme}
   183	            ref={navigationRef}
   184	            linking={linkingConfig}
   185	            documentTitle={{
   186	                enabled: false,
   187	            }}
   188	        >
   189	            {/* HybridAppMiddleware needs to have access to navigation ref and SplashScreenHidden context */}
   190	            <HybridAppMiddleware>
   191	                <AppNavigator authenticated={authenticated} />
   192	            </HybridAppMiddleware>
   193	        </NavigationContainer>
   194	    );
   195	}
   196	
   197	NavigationRoot.displayName = 'NavigationRoot';
   198	
   199	export default NavigationRoot;
